import{_ as o,c as l,o as t,a2 as a}from"./chunks/framework.CFHYvIe4.js";const h=JSON.parse('{"title":"Installation Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":1756461828000}'),i={name:"guide/installation.md"};function n(r,e,s,d,u,c){return t(),l("div",null,e[0]||(e[0]=[a('<h1 id="installation-guide" tabindex="-1">Installation Guide <a class="header-anchor" href="#installation-guide" aria-label="Permalink to &quot;Installation Guide&quot;">​</a></h1><p>This guide covers how to install S1API for both mod users and mod developers.</p><h2 id="for-mod-users" tabindex="-1">For Mod Users <a class="header-anchor" href="#for-mod-users" aria-label="Permalink to &quot;For Mod Users&quot;">​</a></h2><p>If you&#39;re a player who wants to use mods that require S1API, follow these steps:</p><ol><li><p><strong>Install MelonLoader</strong></p><ul><li>Download and install MelonLoader for Schedule One following the <a href="https://melonwiki.xyz/#/README" target="_blank" rel="noreferrer">official MelonLoader installation guide</a>.</li><li>Ensure MelonLoader is properly installed by launching the game once and verifying a <code>Plugins</code> folder was created in your game directory.</li></ul></li><li><p><strong>Install S1API</strong></p><ul><li>Download the latest S1API release ZIP file.</li><li>Drag the <code>Plugins</code> folder into your Schedule One game directory.</li><li>If prompted to replace files, select &quot;Yes&quot;. This should only occur when updating S1API.</li></ul></li><li><p><strong>Verify Installation</strong></p><ul><li>Launch Schedule One.</li><li>If installed correctly, S1API will load with MelonLoader at game startup.</li><li>You can verify the installation by checking the MelonLoader console for S1API messages.</li></ul></li></ol><h2 id="for-mod-developers" tabindex="-1">For Mod Developers <a class="header-anchor" href="#for-mod-developers" aria-label="Permalink to &quot;For Mod Developers&quot;">​</a></h2><p>If you&#39;re a mod developer who wants to use S1API in your mod, follow these steps:</p><ol><li><p><strong>Obtain S1API.Forked</strong></p><ul><li>Install S1API.Forked following the steps in the &quot;For Mod Users&quot; section above.</li></ul></li><li><p><strong>Add S1API.Forked as a Reference</strong></p><ul><li>Install the S1API.Forked NuGet package in your mod project: <ul><li>Using NuGet Package Manager: Search for &quot;S1API.Forked&quot; and install the latest version</li><li>Using Package Manager Console: <code>Install-Package S1API.Forked</code></li><li>Using .NET CLI: <code>dotnet add package S1API.Forked</code></li><li>Using PackageReference: Add <code>&lt;PackageReference Include=&quot;S1API.Forked&quot; Version=&quot;1.6.7&quot; /&gt;</code> to your project file</li></ul></li><li>The NuGet package automatically handles the correct references for both IL2CPP and Mono builds</li></ul><blockquote><p><strong>Important Warning:</strong> Do not add the game&#39;s <code>Assembly-CSharp.dll</code> as a reference when using S1API.Forked unless you know what you are doing. Referencing the game&#39;s assembly directly loses the cross compatability of the API.</p></blockquote></li><li><p><strong>Start Developing</strong></p><ul><li>You can now use the S1API classes and methods in your mod code.</li><li>Import the appropriate namespaces in your code files to access S1API functionality.</li></ul></li><li><p><strong>Publishing Your Mod</strong></p><ul><li>When publishing your mod, always include S1API as a dependency in your documentation.</li><li>Make it clear to users that they need to install S1API for your mod to function properly.</li></ul></li></ol>',8)]))}const g=o(i,[["render",n]]);export{h as __pageData,g as default};
